def fact(n):
    if n <= 1: return 1
    return n * fact(n-1)

def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def fizzbuzz(n):
    if n % 15 == 0: return 'FizzBuzz'
    if n % 3 == 0: return 'Fizz'
    if n % 5 == 0: return 'Buzz'
    return str(n)

def nth_fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0: return False
    return True

def unique(lst):
    seen = []
    for x in lst:
        if x not in seen: seen.append(x)
    return seen

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def running_total(nums):
    out, t = [], 0
    for x in nums:
        t += x
        out.append(t)
    return out
